edits.before:
// Save the element limit
this.maxLength = $module.getAttribute(countAttribute)

// Check for limit
if (!this.maxLength) {
  return
}

// Remove hard limit if set
$module.removeAttribute('maxlength')

this.bindChangeEvents()

edits.after:
// Save the element limit
this.maxLength = $module.getAttribute(countAttribute)

// Check for limit
if (!this.maxLength) {
  return
}

// Remove hard limit if set
this.$textarea.removeAttribute('maxlength')

this.bindChangeEvents()
